<script setup lang="ts">
import { computed, useId } from 'vue'
import type { IntensityMetric } from '../data/intensity'
import type { GuidanceSeries } from '../data/intensity-sources'
import { categories } from '../data/wnc2'
const props=defineProps<{series:GuidanceSeries[];cyclone:string;metric:IntensityMetric;unit?:'kt'|'m/s'|'hPa'}>()
const clip=`intensity-${useId().replace(/:/g,'')}`
const unit=computed(()=>props.unit??(props.metric==='wind'?'kt':'hPa'))
const compatible=computed(()=>props.series.every(s=>(s.unit??(s.metric==='wind'?'kt':'hPa'))===unit.value))
const points=computed(()=>props.series.flatMap(s=>s.points))
const minimumTime=computed(()=>Math.floor(Math.min(...points.value.map(p=>p.time))/21600000)*21600000)
const maximumTime=computed(()=>Math.max(minimumTime.value+21600000,Math.ceil(Math.max(...points.value.map(p=>p.time))/21600000)*21600000))
const step=computed(()=>{const values=points.value.map(p=>p.value),range=props.metric==='wind'?Math.max(20,...values):Math.max(5,Math.max(...values)-Math.min(...values));return [1,2,5,10,20,50,100,200,500,1000].find(s=>s>=range/7)??1000})
const low=computed(()=>props.metric==='wind'?0:Math.floor((Math.min(...points.value.map(p=>p.value))-2)/step.value)*step.value)
const high=computed(()=>Math.max(low.value+step.value,Math.ceil((Math.max(...points.value.map(p=>p.value))+2)/step.value)*step.value))
const yTicks=computed(()=>Array.from({length:Math.min(25,Math.round((high.value-low.value)/step.value)+1)},(_,i)=>low.value+i*step.value))
const xTicks=computed(()=>{const interval=maximumTime.value-minimumTime.value>8*86400000?48*3600000:24*3600000;return Array.from({length:Math.floor((maximumTime.value-minimumTime.value)/interval)+1},(_,i)=>minimumTime.value+i*interval)})
const x=(time:number)=>85+(time-minimumTime.value)/(maximumTime.value-minimumTime.value)*1000
const y=(value:number)=>props.metric==='wind'?570-(value-low.value)/(high.value-low.value)*470:100+(value-low.value)/(high.value-low.value)*470
const curves=computed(()=>props.series.map(s=>({...s,segments:s.points.slice(1).flatMap((p,i)=>{const before=s.points[i]!;return p.time>before.time&&p.time-before.time<=12*3600000?[{point:p,previous:before}]:[]})})))
const label=(time:number)=>new Date(time).toISOString().slice(5,16).replace('T',' ')
const compact=(s:string)=>s.replace('T',' ').replace(/:00(?:\.000)?Z$/,'Z')
const categoryNames:Record<number,string>={0:'DB',25:'TD',34:'TS',64:'C1',83:'C2',96:'C3',113:'C4',137:'C5'}
const ordered=[...categories].reverse()
const bands=computed(()=>props.metric==='wind'&&unit.value==='kt'?ordered.map((c,i)=>({...c,name:categoryNames[c.min],upper:Math.min(high.value,ordered[i+1]?.min??high.value),lower:Math.max(low.value,c.min)})).filter(c=>c.upper>c.lower):[])
const legendRows=computed(()=>Math.ceil(props.series.length/4)),legendY=computed(()=>bands.value.length?701:663),height=computed(()=>legendY.value+legendRows.value*58+105)
const hasSd3=computed(()=>props.series.some(s=>s.model==='SD3')),hasLow=computed(()=>props.series.some(s=>s.definition==='low'))
</script>
<template>
<svg v-if="points.length&&compatible" class="intensity-chart" :viewBox="`0 0 1200 ${height}`" xmlns="http://www.w3.org/2000/svg" role="img" :aria-label="`${cyclone} model ${metric} in native ${unit}, valid time UTC`" style="background:#fff;color:#294459">
<title>{{ cyclone }} · {{ metric==='wind'?`Intensity (${unit})`:'Pressure (hPa)' }} · displayed units; original source fields unchanged</title>
<desc>Source fields unchanged; no pressure-derived wind or intensity calibration. Native AI/SD3 m/s winds are explicitly converted by 3600/1852 for kt display; notes retain the conversion and source definition. This does not reconcile averaging periods or wind definitions. Field-L vector wind is not sustained tracker VMAX. Member means require at least two and 25% of full N; provider means and individual guidance stay distinct. WM-6 valid UTC = forecast_zero + forecast_hour, not provider publication time. No lines across gaps greater than 12h. Existing kt category thresholds/colours unchanged. {{ series.map(s=>`${s.label}: ${s.identity??s.cyclone}; definition=${s.definition}; ${s.initializationLabel??'provider/model init'}=${s.initializationTime}; ${s.baseLabel??'forecast base'}=${s.forecastZero}; N=${s.denominator??'not applicable'}; source=${s.source}; checked=${s.checkedAt}; ${s.note??''}; ${s.attribution??''} ${s.license??''}; `+s.points.map(p=>`${p.validTime} +${p.leadHours}h=${p.value}${unit}, n=${p.count??'unknown'}`).join('; ')).join(' | ') }}</desc>
<rect width="1200" :height="height" fill="white"/><text x="85" y="33" font-size="24" font-weight="bold" fill="currentColor">{{ cyclone }} · {{ metric==='wind'?`Intensity / 风速 (${unit})`:'Pressure / 气压 (hPa)' }}</text><text x="85" y="65" font-size="16" fill="#667e91">Valid UTC · {{ series.length }} source curves · AI m/s ×3600/1852 → kt · No intensity calibration</text>
<rect x="85" y="100" width="1000" height="470" fill="#f0f2f4"/><g class="intensity-category-bands"><rect v-for="b in bands" :key="b.min" :data-min="b.min" :x="85" :y="y(b.upper)" width="1000" :height="y(b.lower)-y(b.upper)" :fill="b.color" fill-opacity=".15"/><text v-for="b in bands.filter(b=>y(b.lower)-y(b.upper)>17)" :key="b.min" x="1095" :y="(y(b.lower)+y(b.upper))/2+5" font-size="17" :fill="b.color==='\u0023f4d500'?'#807100':b.color">{{ b.name }}</text></g>
<defs><clipPath :id="clip"><rect x="85" y="100" width="1000" height="470"/></clipPath></defs>
<g fill="#53697d" font-size="14"><g v-for="v in yTicks" :key="v"><line x1="85" x2="1085" :y1="y(v)" :y2="y(v)" stroke="white"/><text x="74" :y="y(v)+5" text-anchor="end">{{ v }}</text></g><g v-for="time in xTicks" :key="time"><line :x1="x(time)" :x2="x(time)" y1="100" y2="570" stroke="white"/><text :x="x(time)" y="595" :text-anchor="x(time)>1040?'end':'middle'">{{ label(time) }}</text></g></g>
<rect x="85" y="100" width="1000" height="470" fill="none" stroke="#8496a5"/><text x="25" y="335" transform="rotate(-90 25 335)" text-anchor="middle" font-size="16" fill="currentColor">{{ metric==='wind'?`Source wind (${unit})`:'Source pressure (hPa, inverted)' }}</text><text x="580" y="625" text-anchor="middle" font-size="15" fill="#4e6579">Valid time (UTC) · not equal lead hours from different model bases</text>
<g :clip-path="`url(#${clip})`"><g v-for="s in curves" :key="s.key" class="intensity-model-curve" :data-model="s.model" :data-definition="s.definition"><line v-for="p in s.segments" :key="p.point.time" :x1="x(p.previous.time)" :x2="x(p.point.time)" :y1="y(p.previous.value)" :y2="y(p.point.value)" :stroke="s.color" :stroke-width="s.definition==='member_mean'||s.definition==='provider_mean'?3.2:2.5"/><circle v-for="p in s.points" :key="p.time" class="intensity-fix" :cx="x(p.time)" :cy="y(p.value)" r="3.2" :fill="s.color"><title>{{ s.label }} · {{ p.validTime }} · native +{{ p.leadHours }}h · {{ p.value.toFixed(2) }} {{ unit }} · {{ s.definition }}{{ s.denominator===null?' · no ensemble N':` · valid n=${p.count??'unknown'}/${s.denominator}` }}{{ p.min===null?'':` · member range ${p.min.toFixed(1)}–${p.max!.toFixed(1)} ${unit}` }}</title></circle></g></g>
<g v-if="bands.length" class="intensity-category-key" transform="translate(85,660)"><g v-for="(c,i) in ordered" :key="c.min" :transform="`translate(${i*132},0)`"><rect width="18" height="14" :fill="c.color"/><text x="24" y="12" font-size="14" fill="#4e6579">{{ categoryNames[c.min] }} ≥{{ c.min }}</text></g></g>
<g v-for="(s,i) in series" :key="s.key" class="intensity-legend-entry" :transform="`translate(${85+(i%4)*275},${legendY+Math.floor(i/4)*58})`"><line x2="26" :stroke="s.color" stroke-width="3.5"/><text x="34" y="5" font-size="16" :fill="s.color">{{ s.label }} <tspan font-size="12">{{ s.definition==='member_mean'?'mean':s.definition==='provider_mean'?'provider':s.definition==='low'?'local L':s.definition==='aid'?'aid':'single' }}</tspan></text><text y="23" font-size="12" fill="#667e91">{{ s.initializationLabel??(s.model==='wm6'?'Provider run':'Init') }} {{ compact(s.initializationTime) }}{{ s.source==='snapshot'?' OLD SNAPSHOT':'' }}</text><title>{{ s.identity??s.cyclone }} · {{ s.baseLabel??'Forecast base' }} {{ s.forecastZero }} · {{ s.note }}</title></g>
<text x="85" :y="height-79" font-size="13" fill="#596e7e">Member means ≠ provider mean ≠ individual guidance. Missing ≠ zero; wind definitions/averaging periods differ.</text><text x="85" :y="height-58" font-size="13" fill="#596e7e">{{ hasLow?'AIGFS: local L-centre MSLP, not official TC intensity. No wind inferred.':'Native m/s ×3600/1852 → displayed kt; no wind-pressure correction or intensity calibration.' }}</text><text v-if="hasSd3" x="85" :y="height-36" font-size="13" fill="#596e7e">SD3: TianJi Weather Science and Technology Company · https://www.tjweather.com · CC BY-NC 4.0 · Noncommercial only</text><text x="85" :y="height-14" font-size="12" fill="#596e7e">{{ hasSd3?'License: https://creativecommons.org/licenses/by-nc/4.0/ · Directory version and first valid UTC are not verified initialization.':'Source versions, displayed-unit values and conversion notes are included in SVG metadata.' }}</text>
</svg>
<p v-else>{{ compatible?'没有可用强度点，不补造曲线或时间。':'不同风速单位不可混入同一坐标轴。' }}</p>
</template>
<style scoped>.intensity-chart{display:block;width:100%;height:auto;font-family:Arial,sans-serif}</style>
